def measure(tokens, weights, prefix, eot, newline_ids, exact_newline):
    assert len(tokens) == len(weights)
    c = Counter(rows=1, tokens=len(tokens), supervised_positions=int(weights.sum()))
    starts = np.flatnonzero(tokens == prefix[0])
    affected = 0
    for i, start in enumerate(starts):
        if tokens[start + 1] != prefix[1]:
            continue
        c["assistant_turns"] += 1
        end = int(starts[i + 1]) if i + 1 < len(starts) else len(tokens)
        endings = np.flatnonzero(tokens[start + 2:end] == eot) + start + 2
        c["assistant_eot_count"] += len(endings)
        if len(endings) != 1:
            c["assistant_turns_without_exactly_one_eot"] += 1
        for pos in endings:
            if pos + 1 < len(tokens) and int(tokens[pos + 1]) in newline_ids:
                c["assistant_eot_followed_by_newline_token"] += 1
                c["exact_198_newline_after_assistant_eot"] += int(tokens[pos + 1] == exact_newline)
                if weights[pos] > 0:
                    c["supervised_newline_after_assistant_eot"] += 1
                    affected += 1
    c["rows_with_supervised_post_eot_newline"] = int(affected > 0)
    c["supervised_positions_in_affected_rows"] = int(weights.sum()) if affected else 0
    return c
